                                        </button>
                                    }
                                </div>
                            }

                            @if (hoveredMessageId == msg.Id)
                            {
                                <div class="message-actions">
                                    <button class="action-btn" @onclick="() => OpenThreadAsync(msg)" title="Reply">
                                        💬 Reply
                                    </button>
                                    <button class="action-btn react-trigger" @onclick="() => ToggleEmojiPicker(msg.Id)" title="React">
                                        😀 React
                                    </button>
                                </div>
                            }

